CREATE TABLE IF NOT EXISTS gateway_countries (code CHAR(2) PRIMARY KEY, flag TEXT NOT NULL, names JSONB NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE);


ALTER TABLE gateway_user_kyc_documents DROP CONSTRAINT IF EXISTS gateway_user_kyc_documents_type_check;
ALTER TABLE gateway_user_kyc_documents ADD CONSTRAINT gateway_user_kyc_documents_type_check CHECK (
 document_type IN ('ID_CARD','ID_CARD_FRONT','ID_CARD_BACK','ID_CARD_SELFIE','PASSPORT','ADDRESS_PROOF','BUSINESS_LICENSE','FACE_IMAGE')
);
